<?php
declare(strict_types=1);namespace App\Controllers;use App\Policies\AuthPolicy;use App\Services\AccountabilityService;use App\Services\AuditService;use App\Services\ExportService;use App\Support\Database;use App\Support\Security;use App\Support\View;
final class AccountabilityController {public function dashboard(array $p):string{$tid=(int)$p['id'];$u=AuthPolicy::requireTournamentPermission('export',$tid);$db=Database::connection();$jobs=$db->prepare('SELECT id,export_type,status,progress,expires_at,created_at FROM export_jobs WHERE tournament_id=? ORDER BY id DESC LIMIT 20');$jobs->execute([$tid]);return View::render('admin/accountability',['title'=>'Prestacao de contas','tournament_id'=>$tid,'user'=>$u,'metrics'=>(new AccountabilityService($db))->dashboard($tid),'jobs'=>$jobs->fetchAll()]);}public function export(array $p):never{$tid=(int)$p['id'];$u=AuthPolicy::requireTournamentPermission('export',$tid);Security::verifyCsrf($_POST['_csrf']??null);try{$e=new ExportService(Database::connection());$job=$e->create($tid,(int)$u['id'],(string)$_POST['type']);$e->run($job);Security::redirect('/admin/tournaments/'.$tid.'/accountability');}catch(\Throwable $e){http_response_code(422);exit($e->getMessage());}}public function download(array $p):never{$id=(int)$p['job'];$db=Database::connection();$s=$db->prepare('SELECT * FROM export_jobs WHERE id=?');$s->execute([$id]);$job=$s->fetch();if(!$job){http_response_code(404);exit('Exportação não encontrada.');}AuthPolicy::requireTournamentPermission('export',(int)$job['tournament_id']);if($job['status']!=="completed"||!$job['file_path']||($job['expires_at']&&strtotime($job['expires_at'])<time())){http_response_code(404);exit('Exportação indisponível.');}$base=realpath(dirname(__DIR__,2).'/storage/exports');$file=realpath(dirname(__DIR__,2).'/storage/'.ltrim((string)$job['file_path'],'/'));if(!$base||!$file||!str_starts_with($file,$base.DIRECTORY_SEPARATOR)){http_response_code(404);exit('Arquivo indisponível.');}AuditService::record('download_export','export_jobs',$id);header('Content-Type: application/octet-stream');header('Content-Disposition: attachment; filename="exportacao-'.$id.'.'.pathinfo($file,PATHINFO_EXTENSION).'"');header('Content-Length: '.filesize($file));readfile($file);exit;}}
